import hashlib,json,runpy,subprocess,time
from pathlib import Path
r=runpy.run_path('e2e/execution-suite.py');b=Path('.local/e2e');name='validator-names';path=b/(name+'.json');assert not path.exists();build=json.loads((b/'validator-names-build.json').read_text());before=r['snapshot'](str(path),False,include_adapter=True);assert before['image']==build['old_image'];assert before['source_sha256']==build['after']['source_sha256'];started=time.time_ns();(b/(name+'-before.json')).write_text(json.dumps(before,indent=2)+'\n');p=subprocess.run(['node','e2e/validator-names.mjs'],capture_output=True,text=True,timeout=720);log=b/(name+'.log');log.write_text(p.stdout+p.stderr);print(p.stdout,end='');after=r['snapshot'](str(path),False,include_adapter=True);(b/(name+'-after.json')).write_text(json.dumps(after,indent=2)+'\n');report=json.loads(path.read_text());valid=p.returncode==0 and report['completed'] and report['cleanup'] and not report['cleanup_errors'] and len(report['checks'])==4 and all(v['status']=='passed' for v in report['checks']) and report['skipped']==0 and before['source_sha256']==after['source_sha256'] and before['adapter_images']==after['adapter_images'] and after['image']==build['new_image'] and after['report']['mtime_ns']>started
receipt={'completed':bool(valid),'started_at_ns':started,'ended_at_ns':time.time_ns(),'exit_code':p.returncode,'before':before,'after':after,'report':report,'log_sha256':hashlib.sha256(log.read_bytes()).hexdigest()};(b/(name+'-checkpoint.json')).write_text(json.dumps(receipt,indent=2)+'\n');print(json.dumps({'completed':bool(valid),'groups':len(report['checks']),'passed':sum(v['status']=='passed' for v in report['checks']),'cleanup':report['cleanup'],'control_image':after['image'],'source_files':len(before['source_sha256'])}));assert valid,'see_private_validator_names_receipts'
